  end

  def format(value)
    return (value) ? GameData::Item.get(value).name : "-"
  end
end

class SpeciesLister
  def initialize(selection = 0, includeNew = false)
    @selection = selection
    @commands = []
    @ids = []
    @includeNew = includeNew
    @index = 0
  end

  def dispose; end
  def setViewport(viewport); end

  def startIndex
    return @index
  end

  # Sorted alphabetically.
  def commands
    @commands.clear
    @ids.clear
    cmds = []
    idx = 1
    GameData::Species.each_species do |species|
      cmds.push([idx, species.id, species.real_name])
      idx += 1
    end
    cmds.sort! { |a, b| a[2].downcase <=> b[2].downcase }
    if @includeNew
      @commands.push(_INTL("[NEW SPECIES]"))
      @ids.push(true)
    end
    cmds.each do |i|
      @commands.push(sprintf("%03d: %s", i[0], i[2]))
      @ids.push(i[1])
    end
    @index = @selection
    @index = @commands.length - 1 if @index >= @commands.length
    @index = 0 if @index < 0
    return @commands
  end

  def value(index)
    return nil if index < 0
    return @ids[index]
  end

  def refresh(index); end
end

class TrainerTypeLister
  def initialize(selection = 0, includeNew = false)
    @sprite = IconSprite.new(Graphics.width * 3 / 4, ((Graphics.height - 64) / 2) + 64)
    @sprite.z = 2
    @selection = selection
    @commands = []
    @ids = []
    @includeNew = includeNew
    @index = 0
  end

  def dispose
    @sprite.bitmap&.dispose
    @sprite.dispose
  end

  def setViewport(viewport)
    @sprite.viewport = viewport
  end

  def startIndex
    return @index
  end

  def commands
    @commands.clear
    @ids.clear
    cmds = []
    idx = 1
    GameData::TrainerType.each do |tr_type|
      cmds.push([idx, tr_type.id, tr_type.real_name])
      idx += 1
    end
    cmds.sort! { |a, b| a[2] == b[2] ? a[0] <=> b[0] : a[2].downcase <=> b[2].downcase }
    if @includeNew
      @commands.push(_INTL("[NEW TRAINER TYPE]"))
      @ids.push(true)
    end
    cmds.each do |t|
      @commands.push(sprintf("%03d: %s", t[0], t[2]))
      @ids.push(t[1])
    end
    @index = @selection
    @index = @commands.length - 1 if @index >= @commands.length
    @index = 0 if @index < 0
    return @commands
  end

  def value(index)
    return nil if index < 0
    return @ids[index]
  end

  def refresh(index)
    @sprite.bitmap&.dispose
    return if index < 0
    begin
      if @ids[index].is_a?(Symbol)
        @sprite.setBitmap(GameData::TrainerType.front_sprite_filename(@ids[index]), 0)
      else
        @sprite.setBitmap(nil)
      end
    rescue
      @sprite.setBitmap(nil)
    end
    if @sprite.bitmap
      @sprite.ox = @sprite.bitmap.width / 2
      @sprite.oy = @sprite.bitmap.height / 2
    end
  end
end

